mapper.select:
SELECT store_id, store_name, category_id, brand_id
FROM store
WHERE store_id = #{storeId}

SELECT user_card_id, COALESCE(SUM(amount), 0) AS prev_month_spend FROM payment_transaction WHERE user_card_id IN
#{userCardId}
AND is_eligible = 1 AND paid_at >= DATE_FORMAT(NOW() - INTERVAL 1 MONTH, '%Y-%m-01') AND paid_at < DATE_FORMAT(NOW(), '%Y-%m-01') GROUP BY user_card_id

SELECT COALESCE(SUM(discount_amount), 0) AS used_amount,
       COUNT(*)                          AS used_count
FROM payment_transaction
WHERE user_card_id = #{userCardId}
  AND applied_tier_id = #{tierId}
  AND paid_at >= #{periodStart}
